461:   data += tile_list_info_bytes;
462:   uint8_t *output = pbi->tile_list_output;
463:
464:   for (i = 0; i <= pbi->tile_count_minus_1; i++) {
465:     // Process 1 tile.
466:     // Reset the bit reader.
467:     rb->bit_offset = 0;
468:     rb->bit_buffer = data;
469:
470:     // Read out the tile info.
471:     uint32_t tile_info_bytes = 5;
472:     // Set reference for each tile.
473:     int ref_idx = aom_rb_read_literal(rb, 8);
