481:     pbi->dec_tile_col = aom_rb_read_literal(rb, 8);
482:     if (pbi->dec_tile_row < 0 || pbi->dec_tile_col < 0 ||
483:         pbi->dec_tile_row >= cm->tile_rows ||
484:         pbi->dec_tile_col >= cm->tile_cols) {
485:       cm->error.error_code = AOM_CODEC_CORRUPT_FRAME;
486:       return 0;
487:     }
488:
489:     pbi->coded_tile_data_size = aom_rb_read_literal(rb, 16) + 1;
490:     data += tile_info_bytes;
491:     if ((size_t)(data_end - data) < pbi->coded_tile_data_size) {
492:       cm->error.error_code = AOM_CODEC_CORRUPT_FRAME;
493:       return 0;
494:     }
495:
496:     av1_decode_tg_tiles_and_wrapup(pbi, data, data + pbi->coded_tile_data_size,
497:                                    p_data_end, start_tile, end_tile, 0);
498:     uint32_t tile_payload_size = (uint32_t)(*p_data_end - data);
